create or replace function public.publish_live_network_event(p_event_type text, p_location_id uuid default null, p_actor_type text default 'user', p_actor_id uuid default null, p_payload jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path to 'public','auth','extensions','pg_catalog' as $function$ declare v_id uuid; v_user uuid := auth.uid(); v_actor_id uuid; begin if v_user is null then raise exception 'Authentication required'; end if; if nullif(trim(p_event_type),'') is null then raise exception 'event_type is required'; end if; if p_actor_type not in ('user','business','fleet','enterprise') then raise exception 'Invalid actor type'; end if; if p_actor_type='user' then if p_actor_id is not null and p_actor_id<>v_user then raise exception 'actor identity mismatch'; end if; if trim(p_event_type) not like 'user.%' then raise exception 'user actor cannot publish non-user event'; end if; v_actor_id:=v_user; elsif p_actor_type='business' then if p_actor_id is null or not exists(select 1 from public.business_members bm where bm.business_id=p_actor_id and bm.user_id=v_user and bm.role in ('owner','manager')) then raise exception 'business actor access denied'; end if; if trim(p_event_type) not like 'business.%' then raise exception 'business actor cannot publish non-business event'; end if; v_actor_id:=p_actor_id; elsif p_actor_type='fleet' then if p_actor_id is null or not exists(select 1 from public.businesses b join public.business_members bm on bm.business_id=b.id where b.id=p_actor_id and lower(b.business_tier::text)='fleet' and bm.user_id=v_user and bm.role in ('owner','manager')) then raise exception 'fleet actor access denied'; end if; if trim(p_event_type) not like 'fleet.%' then raise exception 'fleet actor cannot publish non-fleet event'; end if; v_actor_id:=p_actor_id; elsif p_actor_type='enterprise' then if p_actor_id is null or not exists(select 1 from public.businesses b join public.business_members bm on bm.business_id=b.id where b.id=p_actor_id and lower(b.business_tier::text)='enterprise' and bm.user_id=v_user and bm.role in ('owner','manager')) then raise exception 'enterprise actor access denied'; end if; if trim(p_event_type) not like 'enterprise.%' then raise exception 'enterprise actor cannot publish non-enterprise event'; end if; v_actor_id:=p_actor_id; end if; insert into public.live_network_events(event_type,location_id,actor_type,actor_id,payload) values(trim(p_event_type),p_location_id,p_actor_type,v_actor_id,coalesce(p_payload,'{}'::jsonb)) returning id into v_id; return v_id; end; $function$;
